<?php
declare(strict_types=1);
namespace App\Services;
use App\Core\Database;
use App\Core\JsonStore;
use App\Repositories\BannerRepository;
use App\Repositories\StoreSettingRepository;
final class PublicStorefrontService {
 public function __construct(private readonly CatalogService $catalog=new CatalogService(),private readonly BannerRepository $banners=new BannerRepository(),private readonly StoreSettingRepository $settings=new StoreSettingRepository(),private readonly JsonStore $store=new JsonStore()){}
 public function products():array{$items=$this->catalog->products();return $items!==[]||Database::configured()?$items:$this->store->read('products.json',self::demoProducts());}
 public function featuredProducts():array{$items=$this->catalog->featuredProducts();return $items!==[]||Database::configured()?$items:array_values(array_filter($this->products(),static fn(array $p):bool=>!empty($p['featured'])));}
 public function categories():array{$items=$this->catalog->categories();return $items!==[]||Database::configured()?$items:self::demoCategories();}
 public function banners():array{return Database::configured()?$this->banners->activeList():$this->store->read('banners.json',[]);}
 public function settings():array{$saved=Database::configured()?$this->settings->all():$this->store->read('store-settings.json',[]);return array_merge(['store_name'=>'موبایل‌استور','phone'=>'','whatsapp'=>'','contact_email'=>'','address'=>'','opening_hours'=>'','instagram_url'=>'','telegram_url'=>'','map_url'=>''],$saved);}
 private static function demoCategories():array{return [['name'=>'گوشی موبایل','slug'=>'phone','description'=>'مدل‌ها و انتخاب‌های روزمره.','image_path'=>'https://images.unsplash.com/photo-1598327105666-5b89351aff97?auto=format&fit=crop&w=500&q=80'],['name'=>'صوتی','slug'=>'audio','description'=>'هدفون، هندزفری و تجربه شنیداری.','image_path'=>'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=500&q=80'],['name'=>'لوازم جانبی','slug'=>'accessory','description'=>'شارژر، کابل، قاب و محافظ.','image_path'=>'https://images.unsplash.com/photo-1586953208448-b95a79798f07?auto=format&fit=crop&w=500&q=80'],['name'=>'گجت هوشمند','slug'=>'gadget','description'=>'ابزارهای کوچک و کاربردی.','image_path'=>'https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&w=500&q=80']];}
 private static function demoProducts():array{return [['name'=>'گوشی هوشمند','slug'=>'demo-smartphone','category_slug'=>'phone','category_name'=>'گوشی موبایل','short_description'=>'نمونه نمایشی برای اتصال کاتالوگ.','image_path'=>'https://images.unsplash.com/photo-1592899677977-9c10ca588bbd?auto=format&fit=crop&w=900&q=82','featured'=>1],['name'=>'هدفون و هندزفری','slug'=>'demo-headphones','category_slug'=>'audio','category_name'=>'صوتی','short_description'=>'برای مکالمه و موسیقی روزمره.','image_path'=>'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=900&q=82','featured'=>1],['name'=>'ساعت هوشمند','slug'=>'demo-watch','category_slug'=>'gadget','category_name'=>'گجت هوشمند','short_description'=>'گجت‌های کاربردی.','image_path'=>'https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&w=900&q=82','featured'=>1],['name'=>'شارژر و لوازم جانبی','slug'=>'demo-accessory','category_slug'=>'accessory','category_name'=>'لوازم جانبی','short_description'=>'لوازم کاربردی برای شارژ و اتصال.','image_path'=>'https://images.unsplash.com/photo-1586953208448-b95a79798f07?auto=format&fit=crop&w=900&q=82','featured'=>1]];}
}